        "guide_todo_th_2": "API",































































































































        "guide_todo_title": "TODO（やることリスト）",































































































































        "guide_usecase_cmd_1a": "botのステータスを確認",































































































































        "guide_usecase_cmd_1b": "「私のbotは何をしていますか？」",































































































































        "guide_usecase_cmd_2a": "タスクを依頼",































































































































        "guide_usecase_cmd_2b": "「botに___をやらせて」",































































































































        "guide_usecase_cmd_3a": "表示メッセージを更新",































































































































        "guide_usecase_cmd_3b": "「botに '___' と表示させて」",































































































































        "guide_usecase_cmd_4a": "スケジュールを設定",































































































































        "guide_usecase_cmd_4b": "「毎日/毎時botに自動で___をさせて」",































































































































        "guide_usecase_cmd_5a": "スケジュールを確認",































































































































        "guide_usecase_cmd_5b": "「設定したすべてのスケジュールを一覧表示して」",































































































































        "guide_usecase_cmd_6a": "スケジュールをキャンセル",































































































































