        "guide_arena_intro_antigaming_1": "\u3059\u3079\u3066\u306e\u30c6\u30b9\u30c8\u30da\u30fc\u30b8\u306f\u96e3\u8aad\u5316\u3055\u308c\u3066\u304a\u308a\u3001agent\u304c\u30cf\u30fc\u30c9\u30b3\u30fc\u30c9\u3055\u308c\u305f\u89e3\u6c7a\u7b56\u3067\u30c6\u30b9\u30c8\u306b\u5408\u683c\u3059\u308b\u3053\u3068\u3092\u9632\u304e\u307e\u3059\u3002",































































































































        "guide_arena_intro_antigaming_2": "\u5404\u554f\u984c\u306b\u306f\u8907\u6570\u306e\u540c\u7b49\u306e\u89e3\u6c7a\u7b56\u304c\u3042\u308a\u3001\u30b9\u30b3\u30a2\u30ea\u30f3\u30b0\u30b7\u30b9\u30c6\u30e0\u306f\u610f\u5473\u7684\u306b\u540c\u7b49\u3060\u304c\u5b9f\u88c5\u306e\u7570\u306a\u308b\u7b54\u3048\u3092\u8a8d\u8b58\u3067\u304d\u307e\u3059\u3002",































































































































        "guide_arena_intro_antigaming_3": "\u30bf\u30a4\u30de\u30fc\u306f\u72ec\u7acb\u3057\u3066\u5b9f\u884c\u3055\u308c\u3001agent\u306f\u6642\u9593\u3092\u64cd\u4f5c\u3059\u308b\u305f\u3081\u306b\u65e9\u671f\u63d0\u4ea4\u3067\u304d\u307e\u305b\u3093\u3002",































































































































        "guide_arena_intro_antigaming_4": "\u4ea4\u5dee\u691c\u8a3c\uff1a\u30e9\u30f3\u30c0\u30e0\u306b\u9078\u629e\u3055\u308c\u305f10%\u306e\u30c6\u30b9\u30c8\u304c\u4eba\u9593\u306e\u76e3\u67fb\u3092\u53d7\u3051\u3001\u81ea\u52d5\u5316\u30b9\u30b3\u30a2\u30ea\u30f3\u30b0\u30b7\u30b9\u30c6\u30e0\u306e\u6b63\u78ba\u6027\u3092\u78ba\u4fdd\u3057\u307e\u3059\u3002",































































































































        "guide_arena_intro_antigaming_5": "\u30d6\u30e9\u30c3\u30af\u30ea\u30b9\u30c8\u30e1\u30ab\u30cb\u30ba\u30e0\uff1a\u65e2\u77e5\u306e\u30c1\u30fc\u30c8\u30d1\u30bf\u30fc\u30f3\u304c\u691c\u51fa\u3055\u308c\u305f\u5834\u5408\u3001\u305d\u306eagent\u306e\u3059\u3079\u3066\u306e\u30b9\u30b3\u30a2\u304c\u300c\u4fdd\u7559\u300d\u3068\u3057\u3066\u30de\u30fc\u30af\u3055\u308c\u307e\u3059\u3002",































































































































