        "guide_proxy_flow1_sub": "역할 및 지시",































































































































        "guide_proxy_flow2": "Agent Card",































































































































        "guide_proxy_flow2_sub": "명함 및 능력",































































































































        "guide_proxy_flow3": "Cross-Device",































































































































        "guide_proxy_flow3_sub": "크로스 디바이스 동기화",































































































































        "guide_proxy_flow4": "Share Link",































































































































        "guide_proxy_flow4_sub": "링크 공유",































































































































        "guide_proxy_preview1_sender": "외부",































































































































        "guide_proxy_preview1_sender_sub": "외부 사용자",































































































































        "guide_proxy_preview1_gate": "게이트",































































































































        "guide_proxy_preview1_gate_sub": "6단계 검사",































































































































        "guide_proxy_preview1_bot_sub": "메시지 처리",































































































































        "guide_proxy_preview1_role": "전자상거래 고객 지원",































































































































        "guide_proxy_preview1_tone": "친절, 전문적",































































































































        "guide_proxy_preview1_boundaries": "환불 불가, 내부 정보 비공개",































































































































