        "analytics_refresh": "새로고침",































































































































        "analytics_total_views": "총 조회수",































































































































        "analytics_unique_ips": "고유 IP",































































































































        "analytics_avg_daily": "일일 평균 조회수",































































































































        "analytics_daily_chart": "일일 조회수",































































































































        "analytics_legend_views": "조회수",































































































































        "analytics_legend_uniq": "고유 IP",































































































































        "analytics_top_paths": "인기 경로",































































































































        "analytics_by_campaign": "UTM 캠페인별",































































































































        "analytics_col_path": "경로",































































































































        "analytics_col_views": "조회수",































































































































        "analytics_col_campaign": "캠페인",































































































































