        "guide_agentcard_mock_tag4": "AI",































































































































        "guide_agentcard_h2_howto": "วิธีตั้งค่า",































































































































        "guide_agentcard_h3_web": "ตั้งค่าผ่าน Web Portal",































































































































        "guide_agentcard_web_li1": "ไปที่หน้า <strong>Dashboard</strong>",































































































































