        "guide_proxy_flow2_sub": "Danh thiếp & Năng lực",































































































































        "guide_proxy_flow3": "Cross-Device",































































































































        "guide_proxy_flow3_sub": "Đồng bộ liên thiết bị",































































































































        "guide_proxy_flow4": "Share Link",































































































































        "guide_proxy_flow4_sub": "Chia sẻ liên kết",































































































































        "guide_proxy_preview1_sender": "Bên ngoài",































































































































        "guide_proxy_preview1_sender_sub": "Người dùng bên ngoài",































































































































        "guide_proxy_preview1_gate": "Cổng",































































































































        "guide_proxy_preview1_gate_sub": "6 kiểm tra",































































































































        "guide_proxy_preview1_bot_sub": "Xử lý tin nhắn",































































































































        "guide_proxy_preview1_role": "Chuyên viên hỗ trợ thương mại điện tử",































































































































        "guide_proxy_preview1_tone": "Thân thiện, Chuyên nghiệp",































































































































        "guide_proxy_preview1_boundaries": "Không hoàn tiền, không tiết lộ thông tin nội bộ",































































































































        "guide_proxy_preview2_name": "ShopBot Pro",































































































































        "guide_proxy_preview2_desc": "Trợ lý mua sắm thông minh 24/7",































































































































        "guide_proxy_preview2_body": "Kiểm tra tồn kho, theo dõi đơn hàng, gợi ý sản phẩm, xử lý câu hỏi thường gặp.",































































































































        "guide_proxy_preview2_tag1": "Tra cứu đơn hàng",































































































































        "guide_proxy_preview2_tag2": "Gợi ý sản phẩm",































































































































        "guide_proxy_preview2_tag3": "Theo dõi vận chuyển",































































































































