        "guide_notes_td_13": "Padam",































































































































        "guide_notes_td_2": "Klik",































































































































        "guide_notes_td_3": "Pengurusan Kategori",































































































































        "guide_notes_td_4": "Bot Baca/Tulis",































































































































        "guide_notes_td_5": "Bot boleh membaca, menambah, mengemas kini, dan memadam nota melalui api",































































































































        "guide_notes_td_6": "Perkongsian Rentas Entiti",































































































































        "guide_notes_td_7": "Semua Entiti pada peranti yang sama boleh mengakses semua nota",































































































































