        "guide_quickstart_app_install": "Pemasangan Aplikasi Android",































































































































        "guide_quickstart_deploy": "Pindah ke Keretapi",































































































































        "guide_quickstart_local_dev": "Pembangunan Bahagian Belakang Tempatan",































































































































        "guide_quickstart_meta": "Pembangunan Tempatan, Penyebaran, Pemasangan Aplikasi Android",































































































































        "guide_quickstart_prereq_android": "Peranti Android 8.0+",































































































































        "guide_quickstart_prereq_node": "Node.js 18+",































































































































        "guide_quickstart_prereq_pg": "PostgreSQL (atau gunakan PostgreSQL yang diuruskan oleh Keretapi)",































































































































        "guide_quickstart_prerequisites": "PRASYARAT",































































































































        "guide_quickstart_step_bind": "Buka Portal Web untuk mengikat entiti AI",































































































































        "guide_quickstart_step_download": "Muat turun <code>.aab</code> / <code>.apk</code> terkini daripada <a href=\"https://github.com/HankHuang0516/EClaw/releases/latest\" target=\"_blank\" rel=\"noopener\">Keluaran GitHub</a>",































































































































        "guide_quickstart_step_wallpaper": "Tetapkan sebagai Tetapan → Panjang Wallpaper Langsung → Masukkan ID peranti <code>anda</code>",































































































































        "guide_quickstart_title": "Memulakan VNC",































































































































        "guide_remote_h2_1": "Butiran Ciri",































































































































        "guide_remote_h2_2": "Mekanisme Keselamatan",































































































































        "guide_remote_h2_3": "Titik Akhir api",































































































































        "guide_remote_h2_4": "Contoh Penggunaan Bot",































































































































        "guide_remote_meta": "Kawalan Misi > Kawalan Jauh <span class=\"mc-label\" style=\"background:rgba(244,67,54,0.15);color:#F44336;\">Pengguna Membolehkan / Bot Melaksanakan</span>",































































































































        "guide_remote_note_1": "Ciri ini dilumpuhkan secara lalai. Anda perlu mendayakannya secara manual dalam Tetapan Aplikasi Kawalan → Jauh dan memberikan kebenaran Perkhidmatan Kebolehcapaian.",































































































































        "guide_remote_p_1": "Membolehkan Bot mengawal UI telefon anda secara automatik. Bot membaca struktur skrin melalui <strong>Pokok Kebolehcapaian</strong> dan menghantar arahan seperti ketik, taip, dan tatal. Keseluruhan proses tidak mengambil tangkapan skrin — Bot hanya melihat elemen teks dan tidak menangkap kandungan visual yang sensitif.",































































































































        "guide_remote_td_1": "Tangkapan Skrin",































































































































        "guide_remote_td_10": "Tatal ke atas atau ke bawah pada elemen yang boleh ditatal",































































































































        "guide_remote_td_11": "Kunci Sistem",































































































































        "guide_remote_td_12": "Kekunci belakang, Kekunci rumah",































































































































        "guide_remote_td_13": "Operasi Autonomi Berbilang Putaran",































































































































        "guide_remote_td_14": "Bot boleh berulang kali menangkap skrin → menganalisis perintah → pelaksanaan untuk menyelesaikan tugas berbilang langkah yang kompleks",































































































































        "guide_remote_td_15": "Dinyahdayakan secara Lalai",































































































































        "guide_remote_td_16": "Ciri DIMATIKAN secara lalai; memerlukan pengguna mendayakannya secara manual",































































































































        "guide_remote_td_17": "Kekunci Pengikat",































































































































        "guide_remote_td_18": "Perlindungan Luar Talian",































































































































        "guide_remote_td_19": "Apabila sambungan Socket.IO telefon terputus, permintaan Bot segera mengembalikan 503",































































































































        "guide_remote_td_2": "Bot meminta pokok semantik skrin semasa (sehingga 300 elemen), termasuk teks, jenis, koordinat, dan sifat yang boleh berinteraksi",































































































































        "guide_remote_td_20": "Tiada Tangkapan Skrin",































































































































        "guide_remote_td_21": "Bot hanya menerima struktur teks (Pokok Kebolehcapaian), tanpa imej, video, atau kandungan visual lain",































































































































        "guide_remote_td_22": "Kadar Mengehadkan",































































































































        "guide_remote_td_23": "Selang masa minimum 500ms antara tangkapan skrin untuk mengelakkan pengundian berlebihan",































































































































