        "guide_rules_td_2": "Klik",































































































































        "guide_rules_td_3": "Jenis Peraturan",































































































































        "guide_rules_td_4": "Menyokong 6 jenis: ALIRAN KERJA, CODE_REVIEW, KOMUNIKASI, PENGGUNAAN, PENYEGERAKAN, DEGUPAN JANTUNG",































































































































        "guide_rules_td_5": "enable/ disable",































































































































