        "guide_schedule_meta": "Kawalan Misi > Jadual <span class=\"mc-label mc-label-shared\">Pengguna + Bot Dikongsi</span>",































































































































        "guide_schedule_p_1": "Ciri Jadual membolehkan pengguna dan Bot menyediakan tugas bermasa. Tugasan dicetuskan secara automatik pada masa yang ditentukan dan status serta keputusan setiap pelaksanaan dijejaki.",































































































































        "guide_schedule_td_1": "Tambah Jadual",































































































































        "guide_schedule_td_10": "Batalkan jadual yang masih belum dilaksanakan",































































































































        "guide_schedule_td_11": "Sejarah Perlaksanaan",































































































































        "guide_schedule_td_12": "Mengarkibkan semua jadual yang dilaksanakan, termasuk masa pelaksanaan, Entiti sasaran dan keputusan",































































































































        "guide_schedule_td_13": "Belum selesai",































































































































        "guide_schedule_td_14": "Jadual dibuat, masa pelaksanaan belum tiba lagi",































































































































        "guide_schedule_td_15": "Ungu",































































































































        "guide_schedule_td_16": "Berlari",































































































































        "guide_schedule_td_17": "Masa pelaksanaan telah tiba, Bot sedang memproses tugas",































































































































        "guide_schedule_td_18": "Biru",































































































































        "guide_schedule_td_19": "Selesai",































































































































        "guide_schedule_td_2": "Klik \"+ Tambah Jadual\" untuk membuat tugasan bermasa dengan masa pelaksanaan, Entiti sasaran dan kandungan tugasan",































































































































        "guide_schedule_td_20": "Tugas telah berjaya dilaksanakan",































































































































        "guide_schedule_td_21": "hijau",































































































































        "guide_schedule_td_22": "gagal",































































































































        "guide_schedule_td_23": "Ralat berlaku semasa pelaksanaan tugas",































































































































        "guide_schedule_td_24": "merah",































































































































        "guide_schedule_td_25": "Senaraikan",































































































































