        "guide_nav_detail_agentcard": "Kad Ejen",































































































































        "guide_nav_detail_crossdevice": "Msg Silang Peranti",































































































































        "guide_identity_title": "Konfigurasi Identiti — Panduan Penuh",































































































































        "guide_identity_meta": "Tentukan peranan, tingkah laku, dan gaya komunikasi ejen anda untuk prestasi AI yang tepat",































































































































        "guide_identity_h2_what": "Apa itu Identiti?",































































































































        "guide_identity_p_what": "Identiti ialah struktur identiti bersatu untuk setiap Entiti, termasuk definisi peranan, arahan tingkah laku, nada dan sempadan. Ia menentukan \"siapa\" ejen AI anda dan \"bagaimana\" ia bertindak. Apabila pengguna luar berinteraksi melalui tetingkap proksi, Identiti ialah asas teras untuk tingkah laku ejen.",































































































































        "guide_identity_note_analogy": "💡 Fikirkan Identiti sebagai \"huraian kerja\" — mentakrifkan dengan jelas tanggungjawab ejen, kaedah kerja dan kawasan luar had supaya AI kekal sejajar dengan jangkaan anda.",































































































































        "guide_identity_h2_fields": "Medan Identiti",































































































































        "guide_identity_th_field": "Kesedaran",































































































































        "guide_identity_th_desc": "Penerangan",































































































































        "guide_identity_th_example": "Contoh",































































































































        "guide_identity_field_role": "Nama peranan yang dimainkan oleh ejen",































































































































        "guide_identity_ex_role": "Sokongan E-dagang, Penasihat Perjalanan, Pembantu Ops IT",































































































































        "guide_identity_field_instructions": "Arahan tingkah laku dan aliran kerja (maksimum 2000 aksara)",































































































































        "guide_identity_ex_instructions": "Apabila menerima pertanyaan pesanan, mula-mula sahkan nombor pesanan, kemudian semak logistik...",































































































































        "guide_identity_field_boundaries": "Senarai perkara yang TIDAK boleh dikendalikan oleh ejen",































































































































        "guide_identity_ex_boundaries": "Tiada bayaran balik, tiada pendedahan harga dalaman",































































































































        "guide_identity_field_tone": "Nada komunikasi",































































































































        "guide_identity_ex_tone": "Mesra, profesional, ringkas",































































































































        "guide_identity_field_language": "Bahasa jawapan lalai",































































































































        "guide_identity_field_soul": "ID Templat Soul Terpakai",































































































































        "guide_identity_field_rules": "Senarai ID Templat Peraturan Terpakai",































































































































        "guide_identity_field_profile": "Profil umum dapat dilihat pada kad",































































































































        "guide_identity_ex_profile": "Sokongan e-dagang profesional, perkhidmatan dalam talian 24/7",































































































































        "guide_identity_h2_howto": "Cara Konfigurasi",































































































































        "guide_identity_h3_web": "Kaedah Portal Web",































































































































        "guide_identity_web_li1": "Pergi ke halaman <strong>Papan Pemuka</strong>",































































































































        "guide_identity_web_li2": "Pilih kad entiti untuk dikonfigurasikan",































































































































        "guide_identity_web_li3": "Klik <strong>Editor Identiti</strong> (🪪ikon)",































































































































        "guide_identity_web_li4": "Isi medan dan klik <strong>Simpan</strong>",































































































































        "guide_identity_preview_role": "Perancang Itinerari Perjalanan",































































































































        "guide_identity_preview_instructions": "Syorkan itinerari berdasarkan bajet, masa, pilihan pelanggan...",































































































































