        "guide_schedule_td_18": "Blue",































































































































        "guide_schedule_td_19": "Completed",































































































































        "guide_schedule_td_2": "Click \\\"+ Add Schedule\\\" to create a timed task with execution time, target Entity, and task content",































































































































        "guide_schedule_td_20": "Task has been successfully executed",































































































































        "guide_schedule_td_21": "Green",































































































































        "guide_schedule_td_22": "Failed",































































































































        "guide_schedule_td_23": "An error occurred during task execution",































































































































        "guide_schedule_td_24": "Red",































































































































        "guide_schedule_td_25": "List",































































































































        "guide_schedule_td_26": "Add",































































































































